import{t as e}from"./jsx-runtime-CY_jTiqj.js";import{B as t,C as n,E as r,M as i,N as a,O as o,P as s,b as c,k as l,l as u,n as d,o as f,p,t as m,v as h}from"./shared-BLp3PbbW.js";import{n as g}from"./sparkles-DROpfoeS.js";import{t as _}from"./refresh-cw-CJsE_zQ7.js";import{t as v}from"./CodeEditor-DqHMt3P8.js";var y=e(),b=`Глава 4 · Блок 14 · Подготовка базы и новой границы хранения`;function x({module:e}){return(0,y.jsxs)(a,{children:[(0,y.jsx)(i,{chip:e??b,title:`JSON и его пределы`,intro:`Мы уже сохраняем задачи Planner в JSON и читаем их после перезапуска. Теперь разберём, какую цену имеет работа с полным снимком и почему два независимых изменения могут перезаписать друг друга.`,tags:[{icon:(0,y.jsx)(g,{size:14}),label:`полный список задач`},{icon:(0,y.jsx)(_,{size:14}),label:`повторные чтение и запись`},{icon:(0,y.jsx)(t,{size:14}),label:`потерянное обновление`}]}),(0,y.jsxs)(s,{number:`00`,title:`От сохранённых задач к новому вопросу`,children:[(0,y.jsx)(o,{children:`После перезапуска Planner снова показывает задачи. Это значит, что данные уже переживают завершение процесса. Но сохранение отвечает только на вопрос, как вернуть данные позже, и ещё не объясняет, что случится с двумя изменениями, начавшимися с одного состояния.`}),(0,y.jsx)(l,{variant:`connected`,items:[{title:`Точка старта`,description:`У нас есть один PlannerService, API и CLI используют общий JSON-путь, а задачи читаются после перезапуска.`},{title:`Новый вопрос`,description:`Что происходит, если два изменения получают разные копии одного списка и по очереди сохраняют его целиком?`},{title:`Результат`,description:`Мы прослеживаем load() и save(), показываем потерянное обновление на учебных снимках и формулируем требования к следующему хранению.`}]}),(0,y.jsx)(`p`,{children:`В предыдущей части курса мы собрали API и CLI вокруг одного сервиса и файлового хранилища. Теперь не будем заново создавать сохранение и не станем менять проект. Сначала посмотрим на знакомые операции, затем разыграем их порядок в маленьком безопасном примере. На следующем шаге появится язык таблиц и запросов, но здесь мы пока остаёмся внутри уже знакомой модели списка.`})]}),(0,y.jsxs)(s,{number:`01`,title:`JSON уже обеспечивает постоянное хранение`,children:[(0,y.jsx)(o,{children:`Постоянное хранение означает, что данные находятся вне памяти завершившегося процесса и могут быть прочитаны при новом запуске. В нашем Planner эту задачу уже выполняют JsonStorage и файл с задачами.`}),(0,y.jsx)(`p`,{children:`Когда мы создаём задачу, сервис передаёт данные хранилищу, а JsonStorage записывает их в файл. При следующем запуске load() снова читает файл и восстанавливает объекты Task. Поэтому слово «постоянное» относится к тому, что состояние переживает перезапуск. Оно не обещает, что хранилище объединит независимые правки или выберет за приложение правильный порядок действий.`}),(0,y.jsx)(`p`,{children:`Представим библиотечный каталог, напечатанный целиком на нескольких страницах. Чтобы найти одну карточку, сотрудник всё равно просматривает этот список; чтобы посчитать книги, он тоже проходит его целиком. Такой каталог похож на JSON-массив и список Task в памяти: отдельная нужная запись находится внутри полного набора. Эта аналогия помогает увидеть объём чтения, но не доказывает, что JSON плох для маленького проекта или что любая база обязательно окажется быстрее.`}),(0,y.jsx)(`p`,{children:`JSON остаётся подходящим началом для нашего Planner: структура проста, данные можно проверить глазами, а существующий путь уже работает. Новый вопрос возникает из конкретного договора операций. Хранилище получает и возвращает список целиком, даже если вызывающей функции нужна одна задача или одно число для статистики.`}),(0,y.jsx)(c,{question:`После перезапуска прежние задачи снова читаются. Что это подтверждает?`,options:[`Данные сохраняются между запусками, но независимые обновления не обязательно объединяются.`,`Каждая запись автоматически защищена от любой одновременной правки.`,`Приложение уже выбирает из файла только одну нужную задачу.`],correctIndex:0,explanation:`Перезапуск показывает, что состояние записано вне процесса. Он ничего не говорит о слиянии двух снимков и о том, какой объём данных прочитан для одной операции.`})]}),(0,y.jsxs)(s,{number:`02`,title:`Знакомые операции проходят через весь список`,children:[(0,y.jsx)(o,{children:`Увидеть ограничение проще по реальному пути вызова: интерфейс обращается к сервису, сервис загружает задачи, а хранилище возвращает весь JSON-набор.`}),(0,y.jsx)(`p`,{children:`В StudyHub API и CLI приходят к одному PlannerService. Метод list_tasks() возвращает результат storage.load(). Метод get_task() тоже сначала загружает список, а затем ищет в нём нужный id. Поиск проходит по загруженным задачам, а get_statistics() получает список, считает выполненные задачи и определяет их общее количество. Чтение одной записи и подсчёт, таким образом, начинаются с полного набора.`}),(0,y.jsx)(`p`,{children:`Изменяющая операция делает следующий шаг. Например, add_task() загружает список, создаёт Task, добавляет её к этому списку и передаёт весь список в storage.save(tasks). Замена, частичное обновление и удаление тоже начинают с load(); когда состояние меняется, сервис сохраняет новый полный список. Чтение и запись здесь не одно действие: сначала функция получает отдельное состояние, потом работает с ним, затем отправляет целое состояние обратно.`}),(0,y.jsx)(v,{caption:`Упрощённая схема изменяющей операции, не полный листинг метода`,code:`tasks = storage.load()
tasks.append(task)
storage.save(tasks)`}),(0,y.jsx)(`p`,{children:`Схема показывает последовательность, а не обязательные три строки любого метода. В действующем add_task() между загрузкой и сохранением также создаётся новая задача. В другом методе сервис может найти запись и заменить её. Главное для нашего вопроса: на входе и выходе storage находится полный список, а не только изменённый объект.`}),(0,y.jsx)(m,{caption:`Полный список проходит от JSON к сервису и возвращается в файл`,orientation:`vertical`,children:(0,y.jsxs)(f,{label:`Путь изменяющей операции Planner`,orientation:`vertical`,className:`lesson-json-snapshot-flow`,children:[(0,y.jsx)(u,{title:`API или CLI`,children:(0,y.jsx)(`p`,{children:`Передаёт команду существующему сервису.`})}),(0,y.jsx)(d,{label:`вызов PlannerService`}),(0,y.jsx)(u,{title:`PlannerService`,children:(0,y.jsx)(`p`,{children:`Запрашивает и получает список задач.`})}),(0,y.jsx)(d,{label:`storage.load(): весь JSON-набор`}),(0,y.jsx)(u,{title:`Список Task в памяти`,children:(0,y.jsx)(`p`,{children:`Сервис находит, добавляет или меняет задачу в полном списке.`})}),(0,y.jsx)(d,{label:`storage.save(tasks): весь список`}),(0,y.jsx)(u,{title:`JsonStorage и файл`,shape:`database`,children:(0,y.jsx)(`p`,{children:`Хранилище записывает сформированный список целиком.`})})]})}),(0,y.jsx)(`p`,{children:`Читаем схему сверху вниз: API или CLI вызывают общий сервис; сервис просит JsonStorage загрузить данные; после изменения сервис отправляет список обратно. Поэтому два интерфейса не создают по отдельному Planner, но каждая операция всё равно использует полное состояние файла. Схема объясняет путь данных, а не скорость на конкретном размере файла.`}),(0,y.jsx)(p,{prompt:`Соединим знакомые методы с тем, что они делают со списком.`,leftTitle:`Метод`,rightTitle:`Работа с данными`,pairs:[{left:`list_tasks()`,right:`Загружает и возвращает полный список`},{left:`get_statistics()`,right:`Загружает список и считает его задачи`},{left:`add_task()`,right:`Загружает, меняет и сохраняет полный список`}],explanation:`Методы читают один и тот же вид данных. При изменении сервис сохраняет весь список, а не отдельную запись.`})]}),(0,y.jsxs)(s,{number:`03`,title:`Два чтения могут дать два независимых снимка`,children:[(0,y.jsx)(o,{children:`Каждый load() читает сохранённые данные в состояние текущего вызова. Если второй вызов начался до того, как первый сохранил результат, он может получить прежнюю версию списка.`}),(0,y.jsx)(`p`,{children:`В нашем StudyHub JsonStorage.load() читает JSON-текст, разбирает его и создаёт список объектов Task из записей. Два вызова load() получают отдельные списки и отдельные объекты. Если сервис A уже изменил одну задачу у себя в памяти, ранее загруженный список сервиса B сам об этой правке не узнает. Для него исходные данные остались такими, какими были в момент его чтения.`}),(0,y.jsx)(`p`,{children:`Назовём состояние из файла S0. Вызов A читает S0, и вызов B тоже читает S0. Каждый получает свой снимок. Здесь «снимок» означает набор данных, полученный чтением в конкретный момент. Это не новая копия файла и не второй источник хранения. Это отдельные объекты в памяти, с которыми сервис выполняет уже знакомые операции.`}),(0,y.jsx)(`p`,{children:`Представим двух работников мастерской с распечаткой общего списка заказов. Оба получили лист до начала изменений. Первый отметил, что один заказ готов, и положил в общий архив новую распечатку целиком. Второй на старом листе отметил другой заказ и тоже заменил архив всем листом. Вторая распечатка не содержит отметку первого, хотя работники меняли разные строки. Здесь распечатки соответствуют результатам load(), отметки локальным изменениям, а замена архива полному save().`}),(0,y.jsx)(`p`,{children:`У аналогии есть граница: реальное приложение выполняет чтение и запись через код и файловую систему, а не через бумажный архив. Пример показывает только, почему независимое состояние не включает чужую правку автоматически. Он не определяет все варианты одновременной записи и не доказывает, как именно поведёт себя любая другая база.`}),(0,y.jsx)(n,{code:`snapshot_a = storage.load()
snapshot_b = storage.load()

snapshot_a[0].mark_done()
storage.save(snapshot_a)
snapshot_b[1].mark_done()
storage.save(snapshot_b)

# обе задачи останутся выполненными`,question:`Какое предположение в последнем комментарии требует исправления?`,options:[`Разные изменённые задачи гарантируют, что полные снимки объединятся при записи.`,`Второй снимок мог быть получен до первой записи и всё ещё содержит старое значение первой задачи.`,`Метод mark_done() сам записывает JSON-файл до вызова save().`],correctIndex:1,explanation:`Второй load() не перечитывает данные после первой записи. Сохранение snapshot_b отправляет целый список из старого состояния, поэтому первая правка может исчезнуть.`})]}),(0,y.jsxs)(s,{number:`04`,title:`Последняя запись полного снимка может затереть первую`,children:[(0,y.jsx)(o,{children:`Рассмотрим один конкретный порядок действий. Он показывает, что разные записи списка тоже могут конфликтовать, если каждая операция сохраняет полный снимок.`}),(0,y.jsx)(`p`,{children:`Сначала оба вызова получают две задачи с одинаковыми исходными значениями. Вызов A меняет название первой задачи и сохраняет свой список S1. Теперь файл содержит это новое название. Но снимок B всё ещё основан на S0. Когда B отмечает вторую задачу и сохраняет S2 целиком, первая запись в S2 снова содержит старое название. Итог содержит правку B, а правка A потеряна.`}),(0,y.jsx)(`p`,{children:`Сосредоточимся на причине: второй вызов не обязан нарушать правило Task, передавать неверный тип или повторять тот же id. Каждая локальная операция может быть допустимой. Потеря возникает потому, что поздняя запись заменяет всё сохранённое состояние версией, полученной раньше. Ошибка находится в ожидании автоматического объединения, которого договор load()/save() не обещает.`}),(0,y.jsx)(`p`,{children:`Пройдём тот же ход в пошаговом примере. Здесь две независимые записи о книгах, а не Task Planner. Поля названы коротко, чтобы видеть состояние каждого снимка и не отвлекаться на детали модели.`}),(0,y.jsx)(h,{code:`snapshot_a = [
    {"id": 1, "title": "Прочитать"},
    {"id": 2, "title": "Проверить тесты"},
]
snapshot_b = [
    {"id": 1, "title": "Прочитать"},
    {"id": 2, "title": "Проверить тесты"},
]
snapshot_a[0]["title"] = "Прочитать главу 2"
stored = snapshot_a
snapshot_b[1]["title"] = "Проверить новые тесты"
stored = snapshot_b
print(stored)`,steps:[{line:0,note:`Мы начинаем с двух независимых списков, полученных из одного состояния S0.`,vars:{S0:`две старые записи`}},{line:4,note:`Снимок B отдельно создаёт те же значения. Его словари не являются объектами из snapshot_a.`,vars:{A:`S0`,B:`S0`}},{line:8,note:`Вызов A меняет первую запись только в snapshot_a.`,vars:{A:`заголовок 1 изменён`,B:`без изменений`}},{line:9,note:`Первая полная запись делает snapshot_a текущим сохранённым списком.`,vars:{stored:`S1 содержит правку A`}},{line:10,note:`Вызов B меняет вторую запись в своей прежней копии S0. Первое изменение в B не переносилось.`,vars:{B:`правка второй записи, первая старая`}},{line:11,note:`Вторая полная запись заменяет stored списком snapshot_b, поэтому заголовок первой записи возвращается к исходному.`,vars:{stored:`S2 содержит правку B, правка A потеряна`}},{line:12,note:`Печать подтверждает итог: вторая запись изменилась, первая осталась в состоянии S0.`,vars:{output:`Прочитать; Проверить новые тесты`}}]}),(0,y.jsx)(`p`,{children:`Этот пример можно выполнить в Python: списки и словари создаются независимо, а присваивание stored = snapshot_b изображает запись всего списка в учебную переменную. В проекте JsonStorage сохраняет сериализованные Task в файл. Мы не запускаем этот пример на рабочем tasks.json, поэтому результат можно повторять, менять порядок и сверять с прогнозом без риска для проекта.`})]}),(0,y.jsxs)(s,{number:`05`,title:`Потребность в новом хранении не выбирает его за нас`,children:[(0,y.jsx)(o,{children:`Теперь мы можем сформулировать наблюдение без общего вывода «JSON плох». Мы знаем, какая часть текущего договора создаёт неудобство и что именно хочется исследовать дальше.`}),(0,y.jsx)(`p`,{children:`Первое наблюдение касается чтения: отдельный поиск или статистика получают полный набор задач и обрабатывают его в Python. Второе касается записи: сервис формирует новый список и сохраняет его целиком. Третье следует из опыта со снимками: если два вызова начали работу с одной старой версией, поздний полный save может убрать правку из предыдущей записи.`}),(0,y.jsx)(`p`,{children:`Сохранение после перезапуска и согласование обновлений отвечают на разные вопросы. Перезапуск проверяет, что данные попали в файл и потом читаются из него. Опыт с двумя снимками проверяет, что происходит при определённой последовательности чтения и записи. Наличие первого свойства не даёт автоматически второго.`}),(0,y.jsx)(`p`,{children:`К следующему механизму хранения у нас появляется понятный запрос: находить нужные записи, выбирать подмножество данных для чтения и описывать несколько связанных изменений как согласованную операцию. Это требования, выведенные из наблюдения. Они ещё не говорят, какие команды использовать, как объявить таблицу или как запускать транзакцию.`}),(0,y.jsx)(`p`,{children:`Даже база данных не исправляет неверные правила приложения сама по себе. Если сервис выберет не ту задачу, ошибётся в проверке или неправильно завершит операцию, новый инструмент хранения не превратит это решение в правильное. На следующем занятии мы получим новые понятия и отдельную учебную базу, чтобы исследовать строки и запросы. Рабочий Planner пока остаётся на JSON.`}),(0,y.jsx)(r,{tone:`info`,children:`Мы установили конкретную границу: полный снимок объясняет объём чтения и возможность потерянной правки. Он не доказывает, что малому проекту обязательно нужна база, и не подсказывает готовую архитектуру следующего шага.`})]}),(0,y.jsxs)(s,{number:`06`,title:`Что мы будем делать в практике`,children:[(0,y.jsx)(o,{children:`Мы исследуем существующие load() и save(), а затем воспроизведём результат на отдельных учебных снимках. Проверяемый итог состоит в конкретном объяснении, какая правка сохранилась и почему другая исчезла.`}),(0,y.jsx)(l,{variant:`connected`,items:[{title:`Проследим методы`,description:`Найдём загрузку списка в list_tasks(), get_statistics() и одной изменяющей операции.`},{title:`Сравним объём чтения`,description:`Объясним, почему чтение одной задачи и подсчёт начинаются с полного набора.`},{title:`Смоделируем снимки`,description:`Сначала предскажем результат двух независимых чтений, затем выполним две записи в учебную переменную.`},{title:`Сформулируем вывод`,description:`Укажем потерянную правку и назовём требования, которые изучим дальше, не меняя проект.`}]}),(0,y.jsx)(`p`,{children:`В исходной части мы опираемся на реальные PlannerService и JsonStorage после предыдущего блока. В опыте используем отдельные словари, похожие на записи Task.to_dict(), но не читаем и не перезаписываем рабочий JSON. Практика не добавляет новый backend, не меняет API или CLI и не требует писать SQL. Она завершится наблюдаемым выводом: второй полный снимок сохранил свою правку, но не включил изменение, которого не было в его копии.`}),(0,y.jsx)(`p`,{children:`Такой результат подготовит вопрос следующего занятия: как адресовать нужные строки и обращаться к ним запросами. Здесь мы только исследуем существующий договор и объясняем его последствия. Повторная регрессия не нужна, потому что код Planner и его постоянные данные остаются без изменений.`})]})]})}export{x as Lesson66};